contracts/common/SecuredSignatureValidat.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;

import {ISignatureValidator, ISignatureValidatorConstants} from "../interfaces/ISignatureValidator.sol";

/**
 * @title Secured Signature Validator
 * @notice Safely validates ERC-1271 contract signatures without propagating reverts.
 */
abstract contract SecuredSignatureValidator is ISignatureValidatorConstants {
    /**
     * @notice Validates an ERC-1271 contract signature, returning `true` if valid and `false` otherwise.
     * @dev This method never reverts. A reverting `isValidSignature` call is treated as an invalid
     *      signature. Exactly 32 bytes must be returned equal to ABI-encoded {EIP1271_MAGIC_VALUE}.
     * @param owner The contract whose `isValidSignature` method is called.
     * @param dataHash The hash of the data that was signed.
     * @param signature The signature bytes passed to `isValidSignature`.
     * @return valid `true` if the signature is valid, `false` otherwise.
     */
    function validateContractSignature(address owner, bytes32 dataHash, bytes memory signature) internal view returns (bool valid) {
        bytes memory data = abi.encodeWithSelector(ISignatureValidator.isValidSignature.selector, dataHash, signature);
        (bool success, bytes memory result) = owner.staticcall(data);
        return success && result.length == 32 && abi.decode(result, (bytes32)) == bytes32(EIP1271_MAGIC_VALUE);
    }
}

contracts/common/SecuredTokenTransfer.so.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;

/**
 * @title Secured Token Transfer
 * @notice Securely transfer tokens, handling non-standard ERC-20 tokens.
 * @author Richard Meissner - @rmeissner
 */
abstract contract SecuredTokenTransfer {
    /**
     * @notice Transfers a token and returns `true` if it was successful, `false` otherwise.
     * @dev It checks the return data of the transfer call and returns true if the transfer was successful.
     *      It doesn't check if the `token` address is a contract or not.
     * @param token Token that should be transferred.
     * @param receiver Receiver to whom the token should be transferred.
     * @param amount The amount of tokens that should be transferred.
     * @return transferred Boolean indicating whether or not the transfer was successful.
     */
    function transferToken(address token, address receiver, uint256 amount) internal returns (bool transferred) {
        // The transfer function selector `0xa9059cbb`, precomputed value of `bytes4(keccak256("transfer(address,uint256)"))`.
        bytes memory data = abi.encodeWithSelector(0xa9059cbb, receiver, amount);
        /* solhint-disable no-inline-assembly */
        /// @solidity memory-safe-assembly
        assembly {
            // We write the return value to scratch space.
            // See <https://docs.soliditylang.org/en/v0.7.6/internals/layout_in_memory.html#layout-in-memory>
            let success := call(sub(gas(), 10000), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            switch returndatasize()
            case 0 {
                transferred := success
            }
            case 0x20 {
                transferred := iszero(or(iszero(success), iszero(mload(0))))
            }
            default {
                transferred := 0
            }
        }
        /* solhint-enable no-inline-assembly */
    }
}

contracts/common/SelfAuthorized.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;

import {ErrorMessage} from "../common/ErrorMessage.sol";

/**
 * @title Self Authorized
 * @notice Authorizes the current contract to perform actions on itself.
 * @author Richard Meissner - @rmeissner
 */
abstract contract SelfAuthorized is ErrorMessage {
    /**
     * @dev Ensure that the `msg.sender` is the current contract.
     */
    function requireSelfCall() private view {
        if (msg.sender != address(this)) revertWithError("GS031");
    }

    /**
     * @notice Ensure that a function is authorized.
     * @dev This modifier authorizes calls by ensuring that the contract called itself.
     */
    modifier authorized() {
        // Modifiers are copied around during compilation. This is a function call to minimise the bytecode size.
        requireSelfCall();
        _;
    }
}

contracts/common/SignatureDecoder.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;

/**
 * @title Signature Decoder
 * @notice Decodes encoded packed signatures bytes.
 * @author Richard Meissner - @rmeissner
 */
abstract contract SignatureDecoder {
    /**
     * @notice Splits signature bytes into its `v`, `r` and `s` components, starting from `pos`.
     * @dev Make sure to perform a bounds check for `pos`, to avoid out of bounds access on `signatures`.
     *      The signature format is a compact form of `r:bytes32 || s:bytes32 || v:uint8`,
     *      where `v` is a single byte and not padded to 32 bytes.
     * @param pos Position to start reading the packed signature components.
     *            Bounds check that `signatures[pos:pos+65]` is valid must be performed by the caller.
     * @param signatures Encoded packed signatures bytes.
     * @return v Recovery ID or Safe signature type.
     * @return r Output value r of the signature.
     * @return s Output value s of the signature.
     */
    function signatureSplit(bytes memory signatures, uint256 pos) internal pure returns (uint8 v, bytes32 r, bytes32 s) {
        /* solhint-disable no-inline-assembly */
        /// @solidity memory-safe-assembly
        assembly {
            let signaturePos := mul(0x41, pos)
            r := mload(add(signatures, add(signaturePos, 0x20)))
            s := mload(add(signatures, add(signaturePos, 0x40)))
            v := byte(0, mload(add(signatures, add(signaturePos, 0x60))))
        }
        /* solhint-enable no-inline-assembly */
    }
}

